pullChangedWorkers(sinceTimestamp) {
  var r = new sn_ws.RESTMessageV2(
    'PrairieViewHR', 'getChangedWorkers');
  r.setStringParameterNoEscape('since', sinceTimestamp);
  r.setRequestHeader('X-PV-API-Key',
    gs.getProperty('u_pv_hr_api_key'));

  var response = r.execute();
  if (response.getStatusCode() != 200) {
    gs.error('PrairieViewHR sync failed');
    return [];
  }
  return JSON.parse(response.getBody()).workers;
}

upsertWorker(worker) {
  var gr = new GlideRecord('sys_user');
  gr.addQuery('u_prairie_employee_id',
    worker.employeeId);
  gr.query();
  var isNew = !gr.next();

  if (isNew) {
    gr.initialize();
    gr.sys_domain = PRAIRIE_VIEW_DOMAIN_ID;
    gr.u_prairie_employee_id = worker.employeeId;
  }
  gr.first_name = worker.firstName;
  gr.active = (worker.status === 'active');
  isNew ? gr.insert() : gr.update();
}
